  "about_items": [
    {
      "n": "#185·09",
      "text": "This mint blouse is crafted from soft silk with a flattering V-neckline and a relaxed fit that drapes elegantly over your frame. Its lightness contrasts beautifully with the structured trousers, creating a balanced and effortless look."
    },
    {
      "n": "#136·15",
      "text": "The lavender headband features large square crystals set against a black braided band, adding a touch of glamour while keeping your hair neatly in place for a polished professional appearance."
    },
    {
      "n": "#59·39",
      "text": "These blue wide-leg trousers are made from a stretchy fabric with an elastic waistband, offering all-day comfort without sacrificing style. Their relaxed silhouette flows gracefully as you move through your workday."
    },
    {
      "n": "#273·21",
      "text": "This brown cashmere scarf is knitted in a fine ribbed texture, providing warmth while adding a sophisticated earth tone that complements the brighter pieces of your outfit."
    },
    {
      "n": "#40·11",
      "text": "The blue loafers feature a sleek design with a durable rubber sole, ensuring stability and comfort as you navigate office floors or commute outside."
    },
    {
      "n": "#318·40",
      "text": "This light blue bag has a structured rectangular shape with a metallic clasp closure, offering both style and practical storage for your essentials during your day."
    }
  ]
